// Terra padrão: Blue Marble 2012 (NASA) como sprite
const EARTH_IMG=new Image(); EARTH_IMG.src="data:image/png;base64,";
const EARTH_CV=document.createElement('canvas'); EARTH_CV.width=EARTH_CV.height=768; const EARTH_TEX=new THREE.CanvasTexture(EARTH_CV); let EARTH_OK=false;
function earthTexSync(){ if(!EARTH_OK&&EARTH_IMG.complete&&EARTH_IMG.naturalWidth){EARTH_CV.getContext('2d').drawImage(EARTH_IMG,0,0,768,768);EARTH_TEX.needsUpdate=true;EARTH_OK=true;} }
function earthSprite(){ const s=new THREE.Sprite(new THREE.SpriteMaterial({map:EARTH_TEX,transparent:true,depthWrite:true,depthTest:true})); s.renderOrder=5; return s; }
// coloca o sprite na frente do centro (cobre o miolo do eixo/partículas) e corrige o tamanho aparente
function placeEarth(s,C,R,fwd,rot){ const d=camera.position.distanceTo(C); const k=fwd*R; const dir=camera.position.clone().sub(C).normalize(); s.position.copy(C).addScaledVector(dir,k);
  s.scale.setScalar(2*R*(d/Math.sqrt(Math.max(d*d-R*R,1e-6)))*((d-k)/d)); earthRot(rot||0); }
let EARTH_R=0; function earthRot(r){ if(!EARTH_OK||Math.abs(r-EARTH_R)<1e-4) return; EARTH_R=r; const x=EARTH_CV.getContext('2d'); x.clearRect(0,0,768,768); x.save(); x.translate(384,384); x.rotate(-r); x.drawImage(EARTH_IMG,-384,-384,768,768); x.restore(); EARTH_TEX.needsUpdate=true; }
